from collections import Counter, deque

def transform(grid):
    h,w=len(grid),len(grid[0])
    color_counts=Counter(v for row in grid for v in row)
    bg=color_counts.most_common(1)[0][0]
    out=[row[:] for row in grid]
    seen=set()
    for r in range(h):
        for c in range(w):
            if grid[r][c]!=bg or (r,c) in seen: continue
            q=deque([(r,c)]);seen.add((r,c)); cells=[]; edges=set()
            while q:
                i,j=q.popleft();cells.append((i,j))
                if i==0:edges.add('top')
                if i==h-1:edges.add('bottom')
                if j==0:edges.add('left')
                if j==w-1:edges.add('right')
                for di,dj in ((1,0),(-1,0),(0,1),(0,-1)):
                    ni,nj=i+di,j+dj
                    if 0<=ni<h and 0<=nj<w and grid[ni][nj]==bg and (ni,nj) not in seen:
                        seen.add((ni,nj));q.append((ni,nj))
            if len(edges)<=1:
                for i,j in cells:out[i][j]=4
    return out

